using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using Object=UnityEngine.Object;
[InitializeOnLoad] public static class GroundingPlayChecks {
 static bool booted;static string report="";public static Dictionary<string,float> Feet=new Dictionary<string,float>();
 static GroundingPlayChecks(){if(SessionState.GetBool("GroundingChecks",false))EditorApplication.update+=Boot;}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/PaintedDimension.unity");SessionState.SetBool("GroundingChecks",true);EditorApplication.isPlaying=true;}
 static void Boot(){EditorApplication.QueuePlayerLoopUpdate();if(!EditorApplication.isPlaying||booted||Time.frameCount<3)return;booted=true;Application.logMessageReceived+=Log;new GameObject("Grounding tests").AddComponent<GroundingRunner>().StartCoroutine("Run");}
 static void Log(string m,string stack,LogType t){if((t==LogType.Error||t==LogType.Exception)&&!stack.Contains("UnityEditor.Search"))Done(1,m+stack);}
 public static void Need(bool ok,string m){if(!ok)throw new Exception(m);report+="PASS "+m+"\n";File.WriteAllText("grounding-checks.txt",report);}
 public static void Done(int code,string m=""){SessionState.SetBool("GroundingChecks",false);File.WriteAllText("grounding-checks.txt",report+m);EditorApplication.Exit(code);}
}
public class GroundingRunner:MonoBehaviour {
 static void Need(bool b,string s)=>GroundingPlayChecks.Need(b,s);
 IEnumerator Run(){var s=DemoSession.Instance;s.Begin();yield return new WaitForSeconds(.6f);var gen=Object.FindAnyObjectByType<LevelGenerator>();Need(gen.LoadAuthoredRoute(),"Full route can load for boss practice");yield return null;
 string path="Assets/Sprites/Characters/Red/Red.png";var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.isReadable=true;imp.SaveAndReimport();var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(path);var px=tex.GetPixels32();foreach(var sp in AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>()){int index=int.Parse(sp.name.Split('_').Last());if(index>=13&&index<=18)continue;int low=(int)sp.rect.yMax;for(int y=(int)sp.rect.y;y<sp.rect.yMax;y++)for(int x=(int)sp.rect.x;x<sp.rect.xMax;x++)if(px[y*tex.width+x].a>128)low=Mathf.Min(low,y);Need(Mathf.Abs((low-sp.rect.y-sp.pivot.y)/sp.pixelsPerUnit+.495f)<.001f,"Grounded visual foot aligned: "+sp.name);}imp.isReadable=false;imp.SaveAndReimport();
 var chunks=gen.startChunks.Take(1).Concat(gen.encounterChunks).Concat(gen.endChunks.Take(1)).ToArray();for(int n=0;n<chunks.Length-1;n++){var end=chunks[n].transform.Find("EndPosition").localPosition;float a=Boundary(chunks[n],end.x),b=Boundary(chunks[n+1],0)+end.y;Need(Mathf.Abs(a-b)<.015f,"Joined underside: "+chunks[n].name+" -> "+chunks[n+1].name+" "+a+" / "+b);}
 var cam=Camera.main;var follow=cam.GetComponent<CameraFollow>();follow.enabled=false;var ascent=Object.FindObjectsByType<Transform>().First(t=>t.name=="10_CrystalAscent_Painted(Clone)");cam.transform.position=new Vector3(ascent.position.x+1,ascent.position.y-1,-44.25f);Capture("joined-underside.png");follow.enabled=true;
 yield return s.BossPractice();yield return null;var boss=Object.FindAnyObjectByType<RiftWarden>();Need(boss!=null&&Mathf.Abs(s.transform.position.x-boss.arenaLeft.position.x-3)<.15f,"Practice shortcut arrives at real boss arena");Need(s.HasSpirit&&s.HasEchoKey&&s.Relays==3&&s.TrialCleared,"Practice unlocks prerequisite abilities and gates");Need(s.GetComponent<PlayerHealth>().currentHealth==100,"Practice restores health");var previousBoss=boss;yield return s.BossPractice();yield return null;Need(Object.FindAnyObjectByType<RiftWarden>()!=previousBoss,"Practice recreates arena for repeatable fresh fight");Need(Object.FindObjectsByType<RiftWarden>().Length==1,"Repeated shortcut leaves one boss only");cam.GetComponent<CameraFollow>().SnapToPlayer();Capture("boss-practice.png");
 GroundingPlayChecks.Done(0);}
 static float Boundary(GameObject root,float x){float min=float.PositiveInfinity;foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){if(f.name!="Painted surface"&&!f.name.StartsWith("Underside join"))continue;foreach(var p in f.sharedMesh.vertices){var v=root.transform.InverseTransformPoint(f.transform.TransformPoint(p));if(Mathf.Abs(v.x-x)<.001f)min=Mathf.Min(min,v.y);}}return min;}
 void Capture(string path){var cam=Camera.main;var rt=new RenderTexture(1600,900,24);rt.Create();cam.targetTexture=rt;cam.aspect=1600f/900;RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=null;rt.Release();Destroy(rt);Destroy(tex);}
}
